int n;
vector<vector<int>> g;

// BFS from start; returns (farthest node, its distance).
pair<int, int> farthest(int start) {
    vector<int> dist(n + 1, -1), q{start};
    dist[start] = 0;
    int best = start;
    for (size_t h = 0; h < q.size(); h++) {
        int u = q[h];
        for (int v : g[u])
            if (dist[v] < 0) {
                dist[v] = dist[u] + 1;
                if (dist[v] > dist[best]) best = v;
                q.push_back(v);
            }
    }
    return {best, dist[best]};
}

