import java.io.*;
import java.util.*;

public class Main {
    static int n;
    static int[] head, nxt, to;

    // BFS from start; returns {farthest node, its distance}.
    static int[] farthest(int start) {
        int[] dist = new int[n + 1], q = new int[n];
        Arrays.fill(dist, -1);
        dist[start] = 0;
        int qh = 0, qt = 0, best = start;
        q[qt++] = start;
        while (qh < qt) {
            int u = q[qh++];
            for (int e = head[u]; e != -1; e = nxt[e]) {
                int v = to[e];
                if (dist[v] < 0) {
                    dist[v] = dist[u] + 1;
                    if (dist[v] > dist[best]) best = v;
                    q[qt++] = v;
                }
            }
        }
        return new int[] {best, dist[best]};
    }

    public static void main(String[] args) throws IOException {
        DataInputStream in = new DataInputStream(new BufferedInputStream(System.in, 1 << 16));
        n = readInt(in);
        head = new int[n + 1];
        Arrays.fill(head, -1);
        nxt = new int[2 * n];
        to = new int[2 * n];
        int m = 0;
        for (int i = 0; i < n - 1; i++) {
            int u = readInt(in), v = readInt(in);
            to[m] = v; nxt[m] = head[u]; head[u] = m++;
            to[m] = u; nxt[m] = head[v]; head[v] = m++;
        }
        System.out.println(farthest(farthest(1)[0])[1]);
    }

    static int readInt(DataInputStream in) throws IOException {
        int c = in.read();
        while (c < '0' || c > '9') c = in.read();
        int r = 0;
        while (c >= '0' && c <= '9') { r = r * 10 + (c - '0'); c = in.read(); }
        return r;
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
)

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<26)
	sc.Split(bufio.ScanWords)
	next := func() int { sc.Scan(); v, _ := strconv.Atoi(sc.Text()); return v }
	n := next()
	g := make([][]int, n+1)
	for i := 0; i < n-1; i++ {
		u, v := next(), next()
		g[u] = append(g[u], v)
		g[v] = append(g[v], u)
	}
	// BFS from start; returns the farthest node and its distance.
	farthest := func(start int) (int, int) {
		dist := make([]int, n+1)
		for i := range dist {
			dist[i] = -1
		}
		dist[start] = 0
		best := start
		q := []int{start}
		for h := 0; h < len(q); h++ {
			u := q[h]
			for _, v := range g[u] {
				if dist[v] < 0 {
					dist[v] = dist[u] + 1
					if dist[v] > dist[best] {
						best = v
					}
					q = append(q, v)
				}
			}
		}
		return best, dist[best]
	}
	end, _ := farthest(1)
	_, d := farthest(end)
	fmt.Println(d)
}
